//! Commands the frontend calls. Typed bindings are generated by tauri-specta.
//!
//! These are thin: parameter marshalling and a call into a crate. Anything
//! resembling logic belongs in a crate where it can be tested.

use crate::AppState;
use aloud_store::{history::Entry, Settings, Stats};
use tauri::State;

/// Commands must return a `Result` the frontend can read; anyhow's error is
/// not serializable, so errors cross the boundary as strings.
type CmdResult<T> = Result<T, String>;

fn to_string_err<T>(result: anyhow::Result<T>) -> CmdResult<T> {
    result.map_err(|e| format!("{e:#}"))
}

#[tauri::command]
#[specta::specta]
pub fn app_version() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}

#[tauri::command]
#[specta::specta]
pub fn get_settings(state: State<'_, AppState>) -> Settings {
    state.settings.lock().map(|s| s.clone()).unwrap_or_default()
}

/// Persists settings and applies them to the running app.
#[tauri::command]
#[specta::specta]
pub fn update_settings(state: State<'_, AppState>, settings: Settings) -> CmdResult<()> {
    to_string_err(settings.save())?;

    // Push the hotkey slice into the live config the listener reads, so a
    // rebind takes effect on the next key event rather than at next launch.
    if let Ok(mut config) = state.hotkey_config.lock() {
        *config = settings.hotkeys.clone();
    }

    let mut current = state
        .settings
        .lock()
        .map_err(|_| "settings lock poisoned")?;
    *current = settings;
    Ok(())
}

#[tauri::command]
#[specta::specta]
pub fn get_stats(state: State<'_, AppState>) -> Stats {
    state.pipeline.stats()
}

#[tauri::command]
#[specta::specta]
pub fn get_history(state: State<'_, AppState>, limit: u32) -> CmdResult<Vec<Entry>> {
    to_string_err(state.pipeline.history(limit as usize))
}

#[tauri::command]
#[specta::specta]
pub fn search_notes(query: String) -> CmdResult<Vec<aloud_notes::SearchResult>> {
    let dir = to_string_err(aloud_notes::directory())?;
    Ok(aloud_notes::search(&query, &aloud_notes::all_notes(&dir)))
}

/// Newest notes, for the empty-query state.
#[tauri::command]
#[specta::specta]
pub fn recent_notes(limit: u32) -> CmdResult<Vec<aloud_notes::Note>> {
    let dir = to_string_err(aloud_notes::directory())?;
    let mut notes = aloud_notes::all_notes(&dir);
    notes.truncate(limit as usize);
    Ok(notes)
}

#[tauri::command]
#[specta::specta]
pub fn input_devices() -> CmdResult<Vec<aloud_audio::AudioDevice>> {
    to_string_err(aloud_audio::input_devices())
}

/// Whether the OS lets us listen for keys. False on macOS until the user
/// grants Accessibility permission.
#[tauri::command]
#[specta::specta]
pub fn hotkeys_permitted() -> bool {
    aloud_hotkey::is_permitted()
}

#[tauri::command]
#[specta::specta]
pub fn paste_again(state: State<'_, AppState>) -> CmdResult<()> {
    to_string_err(state.pipeline.paste_again())
}
